// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, bool shouldFail) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep the scenario wide but admissible: deposit at least MinSum, collect a positive amount <= deposit.
        depositAmount = bound(depositAmount, 1 ether, 1 ether + 1e30);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // Adversarial counterparty that reverts on the payout; the fuzzer chooses whether it reverts.
        RevertingCallee callee = new RevertingCallee(shouldFail);
        address actor = address(callee);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(0);

        (uint256 unlockTimeBefore, uint256 balanceBefore) = c.Acc(actor);
        assertTrue(balanceBefore == depositAmount);

        // Advance past the unlock time set by Put (block.timestamp at Put).
        vm.warp(unlockTimeBefore + 1);

        vm.prank(actor);
        c.Collect(collectAmount);

        (, uint256 balanceAfter) = c.Acc(actor);

        if (shouldFail) {
            // The callee reverted: no value moved, so the reference must leave the balance untouched.
            assertTrue(balanceAfter == balanceBefore);
        } else {
            // The callee accepted: exactly the collected amount was subtracted.
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        }
    }
}

contract RevertingCallee {
    bool private immutable fail;

    constructor(bool _fail) {
        fail = _fail;
    }

    fallback() external payable {
        if (fail) {
            revert();
        }
    }

    receive() external payable {
        if (fail) {
            revert();
        }
    }
}
